\label{T1}
	Let $t=\dim S_m(\Gamma_0(N))\geq 3$, $g$ be genus of $\Gamma_0(N)$.
	Let $N\geq 2$ be such that $g=0$ or $g=t$ and $X_0(N)$ is hyperelliptic. 
Then the number $N(t,d)$ of homogeneous polynomials of degree $d\geq 0$  is equal to
\begin{equation}\label{formula1}
N(t,d)=\binom{t+d-1}{d}-(t-1)d-1.
\end{equation}

\label{T2}
	Let $t=\dim S_m(\Gamma_0(N))\geq 3$, $g$ be genus of $\Gamma_0(N)$.
Then the number $N(t,d)$ of homogeneous polynomials of degree $d\geq 0$  is equal to
 \begin{itemize}
	\item $g=\{1,2\}$ $$N(t,d)=\binom{t+d-1}{d}-(t-1)d-1- (g+(d-2)g)$$
	\item $g>2$ $$N(t,d)=\binom{t+d-1}{d}-(t-1)d-1- ((g-2)+(d-2)(g-1))$$
\end{itemize}

